        'fbb',
        'SELECT\n    SUBSTR(date_hour, 1, 10) AS dt_date,\n    date_hour,\n    SUM(CAST(accept AS BIGINT)) AS total_accept\nFROM hive__aaa__authentication\nGROUP BY ROLLUP (SUBSTR(date_hour, 1, 10), date_hour)\nORDER BY dt_date, date_hour;',
